insert into public.movie_intel (id, verdict_headline, watch_if, skip_if, chips, mood, pace, intensity, attention, themes, vibe, expect, best_for_who, best_for_context, best_for_caution, take_title, take_body, alt_id, alt_reasons, episode_rhythm, hook_expectation, editor)
values ('spider-man-brand-new-day', 'The most grounded Spider-Man yet — big feelings, great fights, a little too much of everything.', '["You want street-level Spidey instead of multiverse math", "Holland''s Peter finally getting dramatic weight interests you", "Top-tier MCU action is reason enough"]'::jsonb, '["Superhero fatigue is real and 2.5 hours is a lot", "You want light, quippy Spider-Man all the way through"]'::jsonb, '["Superhero", "Grounded", "Normal"]'::jsonb, 'Earnest', 'steady', 'moderate', 'normal', '["Isolation", "Responsibility", "Street-level heroism"]'::jsonb, 'Mature and physical — Spidey with bruises', '[{"label": "Action", "value": "Excellent", "level": 3}, {"label": "Emotion", "value": "Strong", "level": 2}, {"label": "Humor", "value": "Present", "level": 2}, {"label": "Length", "value": "Overstuffed", "level": 1}]'::jsonb, 'MCU viewers wanting substance with the spectacle', 'A full-evening event watch', 'Feels half an hour too long, and the villain subplot wanders', 'Growing up suits him', 'Cretton shoots the best-looking Spider-Man of the era, Holland finally gets real dramatic meat, and the Bernthal pairing is comedy gold with an edge. It''s overstuffed — the villain detour costs the relationships time, and the runtime shows. But when it''s Peter, the streets and the fights, it''s the franchise at its most alive.', 'the-odyssey', '["Another full-evening epic — mythic scale instead of Marvel"]'::jsonb, null, null, 'CineTonight Editorial')
